/// Pi's builtin `baseten` provider — 17 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn baseten_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "baseten".to_string(),
        name: "Baseten".to_string(),
        base_url: Some("https://inference.baseten.co/v1".to_string()),
        models: baseten_models(),
        api_key_env: vec!["BASETEN_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

