/// Pi's builtin `google` provider — 22 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn google_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "google".to_string(),
        name: "Google".to_string(),
        base_url: Some("https://generativelanguage.googleapis.com/v1beta".to_string()),
        models: google_models(),
        api_key_env: vec!["GEMINI_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

