/// Pi's builtin `kimi-coding` provider — 4 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn kimi_coding_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "kimi-coding".to_string(),
        name: "Kimi For Coding".to_string(),
        base_url: Some("https://api.kimi.com/coding".to_string()),
        models: kimi_coding_models(),
        api_key_env: Vec::new(),
        has_api_key_auth: true,
        has_oauth_auth: true,
    }
}

