/// Pi's builtin `nvidia` provider — 31 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn nvidia_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "nvidia".to_string(),
        name: "NVIDIA".to_string(),
        base_url: Some("https://integrate.api.nvidia.com/v1".to_string()),
        models: nvidia_models(),
        api_key_env: vec!["NVIDIA_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

