/// Pi's builtin `openai` provider — 38 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn openai_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "openai".to_string(),
        name: "OpenAI".to_string(),
        base_url: Some("https://api.openai.com/v1".to_string()),
        models: openai_models(),
        api_key_env: vec!["OPENAI_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

