/// Pi's builtin `openrouter` provider — 351 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn openrouter_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "openrouter".to_string(),
        name: "OpenRouter".to_string(),
        base_url: Some("https://openrouter.ai/api/v1".to_string()),
        models: openrouter_models(),
        api_key_env: Vec::new(),
        has_api_key_auth: true,
        has_oauth_auth: true,
    }
}

