/// Pi's builtin `qwen-token-plan` provider — 17 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn qwen_token_plan_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "qwen-token-plan".to_string(),
        name: "Qwen Token Plan".to_string(),
        base_url: Some(
            "https://token-plan.ap-southeast-1.maas.aliyuncs.com/compatible-mode/v1".to_string(),
        ),
        models: qwen_token_plan_models(),
        api_key_env: vec!["QWEN_TOKEN_PLAN_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

