/// Pi's builtin `vercel-ai-gateway` provider — 220 models.
///
/// `name`/`baseUrl`/auth flags are the fingerprint's `providers` array; `api_key_env`
/// is the `envApiKeyAuth` table in the generator. `base_url: None` for providers whose
/// `baseUrl` is per-request (bedrock, azure) — matching the oracle.
fn vercel_ai_gateway_provider() -> ProviderDescriptor {
    ProviderDescriptor {
        id: "vercel-ai-gateway".to_string(),
        name: "Vercel AI Gateway".to_string(),
        base_url: Some("https://ai-gateway.vercel.sh".to_string()),
        models: vercel_ai_gateway_models(),
        api_key_env: vec!["AI_GATEWAY_API_KEY".to_string()],
        has_api_key_auth: true,
        has_oauth_auth: false,
    }
}

